r=json.loads(Path('analytic/results/real-results.json').read_text());s=json.loads(Path('run/summary.json').read_text());syn=json.loads(Path('analytic/results/sensitivity.json').read_text());rows=[json.loads(x) for x in Path('run/trajectories.jsonl').read_text().splitlines()];c=next(x for x in json.loads(Path('run/centers.json').read_text()) if x['molecule']=='CC#N');seed=int(hashlib.sha256(c['molecule'].encode()).hexdigest()[:8],16)%2147483646+1;xyz=np.array(c['coordinates']);q=p.paths(xyz,p.BASE_SEED+seed,.20);radius=.2*np.sqrt(len(xyz));v=(q['circular'][0][0]-xyz)/radius;w=(q['circular'][0][32]-xyz)/radius;idx=[*range(0,128,8),127]
